import java.io.*;

public class Main {
    static List<long[]> getSkyline(long[][] buildings) {
        // Write your solution here
        return new ArrayList<>();
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        long[][] buildings = new long[n][3];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < 3; j++) {
                in.nextToken();
                buildings[i][j] = (long) in.nval;
            }
        }
        StringBuilder sb = new StringBuilder();
        for (long[] p : getSkyline(buildings)) sb.append(p[0]).append(" ").append(p[1]).append("\n");
        System.out.print(sb);
    }
}
